{"command":"cat << 'EOF' > models.go
package main

import (
	"fmt"
	"path"
	"strings"
)

type TestEvent struct {
	Time    string  `json:"Time"`
	Action  string  `json:"Action"`
	Package string  `json:"Package"`
	Test    string  `json:"Test"`
	Elapsed float64 `json:"Elapsed"`
	Output  string  `json:"Output"`
}

type Test struct {
	Name    string
	Package string
	Status  string // PASS, FAIL, SKIP
	Elapsed float64
	Output  []string
}

type Package struct {
	Name        string
	Status      string // PASS, FAIL, PANIC, NOTEST
	Elapsed     float64
	Cover       float64
	HasCover    bool
	PassCount   int
	FailCount   int
	SkipCount   int
	IsNoTests   bool
	NoTestsMsg  string
	BuildFailed bool
	Panicked    bool
	PanicTest   string
	Tests       []*Test
	TestMap     map[string]*Test
	Output      []string
}

func NewPackage(name string) *Package {
	return &Package{
		Name:    name,
		TestMap: make(map[string]*Test),
	}
}

func FormattedStatus(status string, useColor bool) string {
	if !useColor {
		return status
	}
	switch status {
	case "PASS":
		return "\033[92mPASS\033[0m"
	case "FAIL":
		return "\033[91mFAIL\033[0m"
	case "SKIP":
		return "\033[93mSKIP\033[0m"
	case "PANIC":
		return "\033[91mPANIC\033[0m"
	case "NOTEST":
		return "\033[93mNOTEST\033[0m"
	default:
		return status
	}
}

func FormattedCover(pkg *Package, compareBase map[string]float64, hasCompare bool, useColor bool) (string, string) {
	if !pkg.HasCover {
		return "--", "--"
	}

	covStr := fmt.Sprintf("%.1f%%", pkg.Cover)
	uncoloredCovStr := covStr

	if hasCompare {
		baseCover, exists := compareBase[pkg.Name]
		if exists {
			diff := pkg.Cover - baseCover
			covStr = fmt.Sprintf("%.1f%% (%+.1f%%)", pkg.Cover, diff)
			uncoloredCovStr = covStr
		} else {
			covStr = fmt.Sprintf("%.1f%% (-)", pkg.Cover)
			uncoloredCovStr = covStr
		}
	}

	if !useColor {
		return covStr, uncoloredCovStr
	}

	var colorCode string
	if pkg.Cover >= 80.0 {
		colorCode = "\033[92m" // Green
	} else if pkg.Cover > 50.0 {
		colorCode = "\033[93m" // Yellow
	} else {
		colorCode = "\033[91m" // Red
	}

	return colorCode + covStr + "\033[0m", uncoloredCovStr
}

func FormattedElapsed(elapsed float64, withSuffix bool) string {
	if withSuffix {
		return fmt.Sprintf("%.2fs", elapsed)
	}
	return fmt.Sprintf("%.2f", elapsed)
}

func PackageDisplayName(pkgName string, trimPath string, smallScreen bool) string {
	if trimPath != "" {
		return strings.TrimPrefix(pkgName, trimPath)
	}
	if smallScreen {
		return path.Base(pkgName)
	}
	return pkgName
}
EOF"}

