	t.IsSeparator = append(t.IsSeparator, true)
}

func (t *Table) formatCell(cell string, uncolored string, colIdx int) string {
	w := t.Widths[colIdx]
	pad := w - len(uncolored)
	if pad < 0 {
		pad = 0
	}

	if t.Alignments[colIdx] == AlignCenter {
		leftPad := pad / 2
		rightPad := pad - leftPad
		return strings.Repeat(" ", leftPad) + cell + strings.Repeat(" ", rightPad)
	}

	// AlignLeft
	return cell + strings.Repeat(" ", pad)
}

func (t *Table) Render() string {
	if len(t.Rows) == 0 {
		return ""
	}

	var sb strings.Builder

	switch t.Format {
	case "plain":
		// Header row
		var hCells []string
		for i, h := range t.Headers {
			hCells = append(hCells, t.formatCell(h, h, i))
		}
		sb.WriteString("  " + strings.Join(hCells, "   ") + "  \n")

		// Calculate total line length
		totalLen := 4
		for i, w := range t.Widths {
			totalLen += w
			if i < len(t.Widths)-1 {
				totalLen += 3
			}
		}
		sb.WriteString(strings.Repeat(" ", totalLen) + "\n")

		// Data rows
		for rIdx, row := range t.Rows {
			if t.IsSeparator[rIdx] {
				sb.WriteString(strings.Repeat(" ", totalLen) + "\n")
				continue
			}
			var rCells []string
			for cIdx, cell := range row {
				uc := t.UncoloredRows[rIdx][cIdx]
				rCells = append(rCells, t.formatCell(cell, uc, cIdx))
			}
			sb.WriteString("  " + strings.Join(rCells, "   ") + "  \n")
		}

	case "markdown":
		// Header row
		var hCells []string
		for i, h := range t.Headers {
			hCells = append(hCells, t.formatCell(h, h, i))
		}
		sb.WriteString("| " + strings.Join(hCells, " | ") + " |\n")

		// Hyphen row
		var dCells []string
		for i := range t.Headers {
			w := t.Widths[i] + 2
			dCells = append(dCells, strings.Repeat("-", w))
		}
		sb.WriteString("|" + strings.Join(dCells, "|") + "|\n")

		// Data rows
		for rIdx, row := range t.Rows {
			if t.IsSeparator[rIdx] {
				continue
			}
			var rCells []string
			for cIdx, cell := range row {
				uc := t.UncoloredRows[rIdx][cIdx]
				rCells = append(rCells, t.formatCell(cell, uc, cIdx))
			}
			sb.WriteString("| " + strings.Join(rCells, " | ") + " |\n")
		}

	default: // "basic"
		// Top border
		var topParts []string
		for _, w := range t.Widths {
			topParts = append(topParts, strings.Repeat("─", w+2))
		}
		sb.WriteString("╭" + strings.Join(topParts, "┬") + "╮\n")

		// Header row
		var hCells []string
		for i, h := range t.Headers {
			hCells = append(hCells, t.formatCell(h, h, i))
		}
		sb.WriteString("│ " + strings.Join(hCells, " │ ") + " │\n")

		// Middle border
		var midParts []string
		for _, w := range t.Widths {
			midParts = append(midParts, strings.Repeat("─", w+2))
		}
		sb.WriteString("├" + strings.Join(midParts, "┼") + "┤\n")

		// Data rows
		for rIdx, row := range t.Rows {
			if t.IsSeparator[rIdx] {
				var emptyParts []string
				for i := range t.Headers {
					emptyParts = append(emptyParts, strings.Repeat(" ", t.Widths[i]+2))
				}
				sb.WriteString("│" + strings.Join(emptyParts, "│") + "│\n")
				continue
			}
			var rCells []string
			for cIdx, cell := range row {
				uc := t.UncoloredRows[rIdx][cIdx]
				rCells = append(rCells, t.formatCell(cell, uc, cIdx))
			}
			sb.WriteString("│ " + strings.Join(rCells, " │ ") + " │\n")
		}

		// Bottom border
		var botParts []string
		for _, w := range t.Widths {
			botParts = append(botParts, strings.Repeat("─", w+2))
		}
		sb.WriteString("╰" + strings.Join(botParts, "┴") + "╯\n")
	}

	return sb.String()
}
EOF"}

