{"command":"cat << 'EOF' > render.go
package main

import (
	"fmt"
	"sort"
	"strings"
)

type RenderOptions struct {
	All          bool
	Pass         bool
	Skip         bool
	NoTests      bool
	SmallScreen  bool
	Slow         int
	Sort         string
	UseColor     bool
	Format       string
	TrimPath     string
	HasCompare   bool
	CompareBase  map[string]float64
}

func RenderFailuresAndPanics(pkgList []*Package, opts RenderOptions) string {
	var sb strings.Builder

	for _, pkg := range pkgList {
		if pkg.Status == "PANIC" {
			var panicLines []string
			if pkg.PanicTest != "" {
				if t, ok := pkg.TestMap[pkg.PanicTest]; ok {
					panicLines = extractPanicLines(t.Output)
				}
			}
			if len(panicLines) == 0 {
				panicLines = extractPanicLines(pkg.Output)
			}

			if opts.Format == "markdown" {
				if pkg.PanicTest != "" {
					sb.WriteString(fmt.Sprintf("## PANIC • %s • %s\n", pkg.Name, pkg.PanicTest))
				} else {
					sb.WriteString(fmt.Sprintf("## PANIC • %s\n", pkg.Name))
				}
				for _, l := range panicLines {
					sb.WriteString(l)
				}
				sb.WriteString("\n")
			} else {
				// Box header
				var inner string
				if pkg.PanicTest != "" {
					inner = fmt.Sprintf("   PANIC  package: %s • %s   ", pkg.Name, pkg.PanicTest)
				} else {
					inner = fmt.Sprintf("   PANIC  package: %s   ", pkg.Name)
				}
				boxW := len(inner)
				top := "┏" + strings.Repeat("━", boxW-2) + "┓\n"
				bot := "┗" + strings.Repeat("━", boxW-2) + "┛\n"

				var mid string
				if opts.UseColor {
					borderColor := "\033[38;5;103m"
					reset := "\033[0m"
					top = borderColor + "┏" + strings.Repeat("━", boxW-2) + "┓" + reset + "\n"
					bot = borderColor + "┗" + strings.Repeat("━", boxW-2) + "┛" + reset + "\n"
					mid = borderColor + "┃" + reset + "   " + "\033[91mPANIC\033[0m" + "  package: "
					if pkg.PanicTest != "" {
						mid += pkg.Name + " • " + pkg.PanicTest
					} else {
						mid += pkg.Name
					}
					mid += "   " + borderColor + "┃" + reset + "\n"
				} else {
					mid = "┃" + inner + "┃\n"
				}

				sb.WriteString(top)
				sb.WriteString(mid)
				sb.WriteString(bot)

				for _, l := range panicLines {
					sb.WriteString(l)
				}
				sb.WriteString("\n")
			}
		} else if pkg.Status == "FAIL" {
			var failedTests []*Test
			for _, t := range pkg.Tests {
				if t.Status == "FAIL" {
					failedTests = append(failedTests, t)
				}
			}

			if len(failedTests) == 0 && !pkg.BuildFailed {
				continue
			}

			if opts.Format == "markdown" {
				sb.WriteString(fmt.Sprintf("## FAIL • %s\n\n```\n", pkg.Name))
				for idx, t := range failedTests {
					if idx > 0 {
						sb.WriteString(strings.Repeat("─", 96) + "\n\n")
					}
					renderCleanTestFailure(&sb, t, false)
				}
				sb.WriteString("```\n\n")
			} else {
				inner := fmt.Sprintf("   FAIL  package: %s   ", pkg.Name)
				boxW := len(inner)
				top := "┏" + strings.Repeat("━", boxW-2) + "┓\n"
				bot := "┗" + strings.Repeat("━", boxW-2) + "┛\n"

				var mid string
				if opts.UseColor {
					borderColor := "\033[38;5;103m"
					reset := "\033[0m"
					top = borderColor + "┏" + strings.Repeat("━", boxW-2) + "┓" + reset + "\n"
					bot = borderColor + "┗" + strings.Repeat("━", boxW-2) + "┛" + reset + "\n"
					mid = borderColor + "┃" + reset + "   " + "\033[91mFAIL\033[0m" + "  package: " + pkg.Name + "   " + borderColor + "┃" + reset + "\n"
				} else {
					mid = "┃" + inner + "┃\n"
				}

				sb.WriteString(top)
				sb.WriteString(mid)
				sb.WriteString(bot)
				sb.WriteString("\n")

				for idx, t := range failedTests {
					if idx > 0 {
						sb.WriteString(strings.Repeat("─", 96) + "\n\n")
					}
					renderCleanTestFailure(&sb, t, opts.UseColor)
				}
			}
		}
	}

	return sb.String()
}

func extractPanicLines(output []string) []string {
	idx := -1
	for i, l := range output {
		if strings.Contains(l, "panic:") {
			idx = i
			break
		}
	}
	if idx != -1 {
		return output[idx:]
	}
	return output
}

func renderCleanTestFailure(sb *strings.Builder, t *Test, useColor bool) {
	var failLines []string
	var bodyLines []string

	for _, l := range t.Output {
		s := strings.TrimSpace(l)
		if strings.HasPrefix(s, "=== RUN") || strings.HasPrefix(s, "=== PAUSE") || strings.HasPrefix(s, "=== CONT") {
			continue
		}
		if strings.HasPrefix(s, "--- FAIL:") {
			failLines = append(failLines, l)
		} else {
			bodyLines = append(bodyLines, l)
		}
	}

	for _, fl := range failLines {
		if useColor {
			sb.WriteString("\033[31m" + strings.TrimSuffix(fl, "\n") + "\033[0m\n")
		} else {
			sb.WriteString(fl)
		}
	}
	sb.WriteString("\n")
	for _, bl := range bodyLines {
		sb.WriteString(bl)
	}
	sb.WriteString("\n")
}

func RenderTestTable(pkgList []*Package, opts RenderOptions) string {
	if !opts.All && !opts.Pass && !opts.Skip {
		return ""
	}

	type PkgTests struct {
		Pkg   *Package
		Tests []*Test
	}

	var allPkgTests []PkgTests
	totalTests := 0

	for _, pkg := range pkgList {
		var matched []*Test
		var passList []*Test
		var skipList []*Test
		var failList []*Test

		for _, t := range pkg.Tests {
			if t.Status == "FAIL" {
				failList = append(failList, t)
			} else if t.Status == "PASS" && (opts.All || opts.Pass) {
				passList = append(passList, t)
			} else if t.Status == "SKIP" && (opts.All || opts.Skip) {
				skipList = append(skipList, t)
			}
		}

		if opts.Slow > 0 {
			sort.Slice(passList, func(i, j int) bool { return passList[i].Elapsed > passList[j].Elapsed })
			if len(passList) > opts.Slow {
				passList = passList[:opts.Slow]
			}
			sort.Slice(skipList, func(i, j int) bool { return skipList[i].Elapsed > skipList[j].Elapsed })
			if len(skipList) > opts.Slow {
				skipList = skipList[:opts.Slow]
			}
		}

		matched = append(matched, passList...)
		matched = append(matched, skipList...)
		matched = append(matched, failList...)

		sort.Slice(matched, func(i, j int) bool { return matched[i].Elapsed > matched[j].Elapsed })

		if len(matched) > 0 {
			allPkgTests = append(allPkgTests, PkgTests{Pkg: pkg, Tests: matched})
			totalTests += len(matched)
		}
	}

	if totalTests == 0 {
		return ""
	}

	var sb strings.Builder

	if opts.Format == "markdown" {
		for _, pt := range allPkgTests {
			pkg := pt.Pkg
			sb.WriteString(fmt.Sprintf("## 📦 Package **`%s`**\n\n", pkg.Name))
			sb.WriteString(fmt.Sprintf("Tests: ✓ %d passed | %d skipped | %d failed\n\n", pkg.PassCount, pkg.SkipCount, pkg.FailCount))
			sb.WriteString("<details>\n\n<summary>Click for test summary</summary>\n\n")

			headers := []string{"Status", "Elapsed", "Test"}
			alignments := []Alignment{AlignCenter, AlignCenter, AlignLeft}
			tbl := NewTable(headers, alignments, opts.Format)

			for _, t := range pt.Tests {
				stColored := FormattedStatus(t.Status, opts.UseColor)
				elStr := FormattedElapsed(t.Elapsed, false)
				tbl.AddRow([]string{stColored, elStr, t.Name}, []string{t.Status, elStr, t.Name})
			}

			sb.WriteString(tbl.Render())
			sb.WriteString("</details>\n\n\n")
		}
	} else {
		headers := []string{"Status", "Elapsed", "Test", "Package"}
		alignments := []Alignment{AlignCenter, AlignCenter, AlignLeft, AlignLeft}
		tbl := NewTable(headers, alignments, opts.Format)

		for pkgIdx, pt := range allPkgTests {
			if pkgIdx > 0 {
				tbl.AddSeparatorRow()
			}
			pkgDisp := PackageDisplayName(pt.Pkg.Name, opts.TrimPath, opts.SmallScreen)
			for _, t := range pt.Tests {
				stColored := FormattedStatus(t.Status, opts.UseColor)
				elStr := FormattedElapsed(t.Elapsed, false)
				tbl.AddRow([]string{stColored, elStr, t.Name, pkgDisp}, []string{t.Status, elStr, t.Name, pkgDisp})
			}
		}

		sb.WriteString(tbl.Render())
	}

	return sb.String()
}

func RenderPackageSummaryTable(pkgList []*Package, opts RenderOptions) string {
	var displayPkgs []*Package

	allNotests := true
	for _, pkg := range pkgList {
		if pkg.Status != "NOTEST" {
			allNotests = false
			break
		}
	}

	for _, pkg := range pkgList {
		if pkg.Status != "NOTEST" || opts.NoTests || allNotests {
			displayPkgs = append(displayPkgs, pkg)
		}
	}

	if len(displayPkgs) == 0 {
		return ""
	}

	// Sort displayPkgs
	switch opts.Sort {
	case "elapsed":
		sort.Slice(displayPkgs, func(i, j int) bool {
			if displayPkgs[i].Elapsed == displayPkgs[j].Elapsed {
				return displayPkgs[i].Name < displayPkgs[j].Name
			}
			return displayPkgs[i].Elapsed > displayPkgs[j].Elapsed
		})
	case "cover":
		sort.Slice(displayPkgs, func(i, j int) bool {
			if displayPkgs[i].HasCover != displayPkgs[j].HasCover {
				return displayPkgs[i].HasCover
			}
			if displayPkgs[i].Cover == displayPkgs[j].Cover {
				return displayPkgs[i].Name < displayPkgs[j].Name
			}
			return displayPkgs[i].Cover > displayPkgs[j].Cover
		})
	default: // "name"
		sort.Slice(displayPkgs, func(i, j int) bool {
			return displayPkgs[i].Name < displayPkgs[j].Name
		})
	}

	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	alignments := []Alignment{AlignCenter, AlignCenter, AlignLeft, AlignCenter, AlignCenter, AlignCenter, AlignCenter}
	tbl := NewTable(headers, alignments, opts.Format)

	for _, pkg := range displayPkgs {
		pkgDisp := PackageDisplayName(pkg.Name, opts.TrimPath, opts.SmallScreen)
		stColored := FormattedStatus(pkg.Status, opts.UseColor)
		elStr := FormattedElapsed(pkg.Elapsed, true)
		covColored, covUncolored := FormattedCover(pkg, opts.CompareBase, opts.HasCompare, opts.UseColor)

		if pkg.Status == "NOTEST" {
			tbl.AddRow(
				[]string{stColored, elStr, pkgDisp, covColored, "--", "--", "--"},
				[]string{"NOTEST", elStr, pkgDisp, covUncolored, "--", "--", "--"},
			)
			tbl.AddRow(
				[]string{"", "", pkg.NoTestsMsg, "", "", "", ""},
				[]string{"", "", pkg.NoTestsMsg, "", "", "", ""},
			)
		} else if pkg.Status == "PANIC" {
			tbl.AddRow(
				[]string{stColored, elStr, pkgDisp, covColored, "--", "--", "--"},
				[]string{"PANIC", elStr, pkgDisp, covUncolored, "--", "--", "--"},
			)
		} else {
			passStr := fmt.Sprintf("%d", pkg.PassCount)
			failStr := fmt.Sprintf("%d", pkg.FailCount)
			skipStr := fmt.Sprintf("%d", pkg.SkipCount)
			tbl.AddRow(
				[]string{stColored, elStr, pkgDisp, covColored, passStr, failStr, skipStr},
				[]string{pkg.Status, elStr, pkgDisp, covUncolored, passStr, failStr, skipStr},
			)
		}
	}

	return tbl.Render()
}
EOF"}

{"command":"cat << 'EOF' > main.go
package main

import (
	"flag"
	"fmt"
	"io"
	"os"
)

const usageStr = `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output. 
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`

func main() {
	var (
		showHelp         bool
		showVersion      bool
		showVersionAlt   bool
		allTests         bool
		passTests        bool
		skipTests        bool
		noTests          bool
		smallScreen      bool
		slowCount        int
		sortAttr         string
		noColor          bool
		formatType       string
		fileName         string
		follow           bool
		followOutput     string
		includeTimestamp bool
		progress         bool
		compareFile      string
		trimPath         string
	)

	flag.CommandLine.Usage = func() {
		fmt.Print(usageStr)
	}

	flag.BoolVar(&showHelp, "h", false, "Show help.")
	flag.BoolVar(&showVersion, "v", false, "Show version.")
	flag.BoolVar(&showVersionAlt, "version", false, "Show version.")
	flag.BoolVar(&allTests, "all", false, "")
	flag.BoolVar(&passTests, "pass", false, "")
	flag.BoolVar(&skipTests, "skip", false, "")
	flag.BoolVar(&noTests, "notests", false, "")
	flag.BoolVar(&smallScreen, "smallscreen", false, "")
	flag.IntVar(&slowCount, "slow", 0, "")
	flag.StringVar(&sortAttr, "sort", "name", "")
	flag.BoolVar(&noColor, "nocolor", false, "")
	flag.StringVar(&formatType, "format", "basic", "")
	flag.StringVar(&fileName, "file", "", "")
	flag.BoolVar(&follow, "follow", false, "")
	flag.StringVar(&followOutput, "follow-output", "", "")
	flag.BoolVar(&includeTimestamp, "include-timestamp", false, "")
	flag.BoolVar(&progress, "progress", false, "")
	flag.StringVar(&compareFile, "compare", "", "")
	flag.StringVar(&trimPath, "trimpath", "", "")

	flag.Parse()

	if showHelp {
		fmt.Print(usageStr)
		os.Exit(0)
	}

	if showVersion || showVersionAlt {
		fmt.Println("tparse version: (devel)")
		os.Exit(0)
	}

	if sortAttr != "name" && sortAttr != "elapsed" && sortAttr != "cover" {
		fmt.Fprintf(os.Stderr, "invalid option:\"%s\". The -sort flag must be one of: name, elapsed or cover\n", sortAttr)
		os.Exit(0)
	}

	if formatType != "basic" && formatType != "plain" && formatType != "markdown" {
		fmt.Fprintf(os.Stderr, "invalid option:\"%s\". The -format flag must be one of: basic, plain or markdown\n", formatType)
		os.Exit(0)
	}

	useColor := !noColor && os.Getenv("NO_COLOR") == ""

	var r io.Reader
	if fileName != "" {
		f, err := os.Open(fileName)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		r = f
	} else {
		fi, err := os.Stdin.Stat()
		if err == nil && (fi.Mode()&os.ModeCharDevice) != 0 {
			fmt.Fprintln(os.Stderr, "stdin must be a pipe, or use -file to open a go test output file")
			os.Exit(1)
		}
		r = os.Stdin
	}

	var followWriter io.Writer
	if followOutput != "" {
		fw, err := os.Create(followOutput)
		if err == nil {
			defer fw.Close()
			followWriter = fw
		}
	}

	streamOpts := StreamOptions{
		Follow:           follow,
		FollowWriter:     followWriter,
		IncludeTimestamp: includeTimestamp,
		Progress:         progress,
		UseColor:         useColor,
	}

	_, pkgList, err := ParseStream(r, streamOpts)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		os.Exit(1)
	}

	compareBase := make(map[string]float64)
	hasCompare := false
	if compareFile != "" {
		if cf, err := os.Open(compareFile); err == nil {
			_, basePkgList, err2 := ParseStream(cf, StreamOptions{})
			cf.Close()
			if err2 == nil {
				hasCompare = true
				for _, pkg := range basePkgList {
					if pkg.HasCover {
						compareBase[pkg.Name] = pkg.Cover
					}
				}
			}
		}
	}

	renderOpts := RenderOptions{
		All:         allTests,
		Pass:        passTests,
		Skip:        skipTests,
		NoTests:     noTests,
		SmallScreen: smallScreen,
		Slow:        slowCount,
		Sort:        sortAttr,
		UseColor:    useColor,
		Format:      formatType,
		TrimPath:    trimPath,
		HasCompare:  hasCompare,
		CompareBase: compareBase,
	}

	failuresStr := RenderFailuresAndPanics(pkgList, renderOpts)
	if failuresStr != "" {
		fmt.Print(failuresStr)
	}

	testTableStr := RenderTestTable(pkgList, renderOpts)
	if testTableStr != "" {
		fmt.Print(testTableStr)
	}

	pkgTableStr := RenderPackageSummaryTable(pkgList, renderOpts)
	if pkgTableStr != "" {
		fmt.Print(pkgTableStr)
	}

	hasFailures := false
	for _, pkg := range pkgList {
		if pkg.Status == "FAIL" || pkg.Status == "PANIC" || pkg.BuildFailed {
			hasFailures = true
			break
		}
	}

	if hasFailures {
		os.Exit(1)
	}
	os.Exit(0)
}
EOF"}

