package main

import (
	"flag"
	"fmt"
	"io"
	"os"
)

const usageStr = `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output. 
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`

func main() {
	var (
		showHelp         bool
		showVersion      bool
		showVersionAlt   bool
		allTests         bool
		passTests        bool
		skipTests        bool
		noTests          bool
		smallScreen      bool
		slowCount        int
		sortAttr         string
		noColor          bool
		formatType       string
		fileName         string
		follow           bool
		followOutput     string
		includeTimestamp bool
		progress         bool
		compareFile      string
		trimPath         string
	)

	flag.CommandLine.Usage = func() {
		fmt.Print(usageStr)
	}

	flag.BoolVar(&showHelp, "h", false, "Show help.")
	flag.BoolVar(&showVersion, "v", false, "Show version.")
	flag.BoolVar(&showVersionAlt, "version", false, "Show version.")
	flag.BoolVar(&allTests, "all", false, "")
	flag.BoolVar(&passTests, "pass", false, "")
	flag.BoolVar(&skipTests, "skip", false, "")
	flag.BoolVar(&noTests, "notests", false, "")
	flag.BoolVar(&smallScreen, "smallscreen", false, "")
	flag.IntVar(&slowCount, "slow", 0, "")
	flag.StringVar(&sortAttr, "sort", "name", "")
	flag.BoolVar(&noColor, "nocolor", false, "")
	flag.StringVar(&formatType, "format", "basic", "")
	flag.StringVar(&fileName, "file", "", "")
	flag.BoolVar(&follow, "follow", false, "")
	flag.StringVar(&followOutput, "follow-output", "", "")
	flag.BoolVar(&includeTimestamp, "include-timestamp", false, "")
	flag.BoolVar(&progress, "progress", false, "")
	flag.StringVar(&compareFile, "compare", "", "")
	flag.StringVar(&trimPath, "trimpath", "", "")

	flag.Parse()

	if showHelp {
		fmt.Print(usageStr)
		os.Exit(0)
	}

	if showVersion || showVersionAlt {
		fmt.Println("tparse version: (devel)")
		os.Exit(0)
	}

	if sortAttr != "name" && sortAttr != "elapsed" && sortAttr != "cover" {
		fmt.Fprintf(os.Stderr, "invalid option:\"%s\". The -sort flag must be one of: name, elapsed or cover\n", sortAttr)
		os.Exit(0)
	}

	if formatType != "basic" && formatType != "plain" && formatType != "markdown" {
		fmt.Fprintf(os.Stderr, "invalid option:\"%s\". The -format flag must be one of: basic, plain or markdown\n", formatType)
		os.Exit(0)
	}

	useColor := !noColor && os.Getenv("NO_COLOR") == ""

	var r io.Reader
	if fileName != "" {
		f, err := os.Open(fileName)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		r = f
	} else {
		fi, err := os.Stdin.Stat()
		if err == nil && (fi.Mode()&os.ModeCharDevice) != 0 {
			fmt.Fprintln(os.Stderr, "stdin must be a pipe, or use -file to open a go test output file")
			os.Exit(1)
		}
		r = os.Stdin
	}

	var followWriter io.Writer
	if followOutput != "" {
		fw, err := os.Create(followOutput)
		if err == nil {
			defer fw.Close()
			followWriter = fw
		}
	}

	streamOpts := StreamOptions{
		Follow:           follow,
		FollowWriter:     followWriter,
		IncludeTimestamp: includeTimestamp,
		Progress:         progress,
		UseColor:         useColor,
	}

	_, pkgList, err := ParseStream(r, streamOpts)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		os.Exit(1)
	}

	compareBase := make(map[string]float64)
	hasCompare := false
	if compareFile != "" {
		if cf, err := os.Open(compareFile); err == nil {
			_, basePkgList, err2 := ParseStream(cf, StreamOptions{})
			cf.Close()
			if err2 == nil {
				hasCompare = true
				for _, pkg := range basePkgList {
					if pkg.HasCover {
						compareBase[pkg.Name] = pkg.Cover
					}
				}
			}
		}
	}

	renderOpts := RenderOptions{
		All:         allTests,
		Pass:        passTests,
		Skip:        skipTests,
		NoTests:     noTests,
		SmallScreen: smallScreen,
		Slow:        slowCount,
		Sort:        sortAttr,
		UseColor:    useColor,
		Format:      formatType,
		TrimPath:    trimPath,
		HasCompare:  hasCompare,
		CompareBase: compareBase,
	}

	failuresStr := RenderFailuresAndPanics(pkgList, renderOpts)
	if failuresStr != "" {
		fmt.Print(failuresStr)
	}

	testTableStr := RenderTestTable(pkgList, renderOpts)
	if testTableStr != "" {
		fmt.Print(testTableStr)
	}

	pkgTableStr := RenderPackageSummaryTable(pkgList, renderOpts)
	if pkgTableStr != "" {
		fmt.Print(pkgTableStr)
	}

	hasFailures := false
	for _, pkg := range pkgList {
		if pkg.Status == "FAIL" || pkg.Status == "PANIC" || pkg.BuildFailed {
			hasFailures = true
			break
		}
	}

	if hasFailures {
		os.Exit(1)
	}
	os.Exit(0)
}
