package main

import (
	"strings"
)

type Alignment int

const (
	AlignLeft Alignment = iota
	AlignCenter
)

type Table struct {
	Headers       []string
	Alignments    []Alignment
	Format        string
	Rows          [][]string
	UncoloredRows [][]string
	IsSeparator   []bool
	Widths        []int
}

func NewTable(headers []string, alignments []Alignment, format string) *Table {
	widths := make([]int, len(headers))
	for i, h := range headers {
		widths[i] = len(h)
	}
	return &Table{
		Headers:    headers,
		Alignments: alignments,
		Format:     format,
		Widths:     widths,
	}
}

func (t *Table) AddRow(cells []string, uncoloredCells []string) {
	t.Rows = append(t.Rows, cells)
	t.UncoloredRows = append(t.UncoloredRows, uncoloredCells)
	t.IsSeparator = append(t.IsSeparator, false)

	for i, uc := range uncoloredCells {
		if i < len(t.Widths) {
			if len(uc) > t.Widths[i] {
				t.Widths[i] = len(uc)
			}
		}
	}
}

func (t *Table) AddSeparatorRow() {
	emptyCells := make([]string, len(t.Headers))
	t.Rows = append(t.Rows, emptyCells)
	t.UncoloredRows = append(t.UncoloredRows, emptyCells)
	t.IsSeparator = append(t.IsSeparator, true)
}

func (t *Table) formatCellWithAlign(cell string, uncolored string, colIdx int, align Alignment) string {
	w := t.Widths[colIdx]
	pad := w - len(uncolored)
	if pad < 0 {
		pad = 0
	}

	if align == AlignCenter {
		leftPad := pad / 2
		rightPad := pad - leftPad
		return strings.Repeat(" ", leftPad) + cell + strings.Repeat(" ", rightPad)
	}

	// AlignLeft
	return cell + strings.Repeat(" ", pad)
}

func (t *Table) formatCell(cell string, uncolored string, colIdx int) string {
	return t.formatCellWithAlign(cell, uncolored, colIdx, t.Alignments[colIdx])
}

func (t *Table) Render() string {
	if len(t.Rows) == 0 {
		return ""
	}

	var sb strings.Builder

	switch t.Format {
	case "plain":
		// Header row (centered headers)
		var hCells []string
		for i, h := range t.Headers {
			hCells = append(hCells, t.formatCellWithAlign(h, h, i, AlignCenter))
		}
		sb.WriteString("  " + strings.Join(hCells, "   ") + "  \n")

		// Calculate total line length
		totalLen := 4
		for i, w := range t.Widths {
			totalLen += w
			if i < len(t.Widths)-1 {
				totalLen += 3
			}
		}
		sb.WriteString(strings.Repeat(" ", totalLen) + "\n")

		// Data rows
		for rIdx, row := range t.Rows {
			if t.IsSeparator[rIdx] {
				sb.WriteString(strings.Repeat(" ", totalLen) + "\n")
				continue
			}
			var rCells []string
			for cIdx, cell := range row {
				uc := t.UncoloredRows[rIdx][cIdx]
				rCells = append(rCells, t.formatCell(cell, uc, cIdx))
			}
			sb.WriteString("  " + strings.Join(rCells, "   ") + "  \n")
		}

	case "markdown":
		// Header row (centered headers)
		var hCells []string
		for i, h := range t.Headers {
			hCells = append(hCells, t.formatCellWithAlign(h, h, i, AlignCenter))
		}
		sb.WriteString("| " + strings.Join(hCells, " | ") + " |\n")

		// Hyphen row
		var dCells []string
