			w := t.Widths[i] + 2
			dCells = append(dCells, strings.Repeat("-", w))
		}
		sb.WriteString("|" + strings.Join(dCells, "|") + "|\n")

		// Data rows
		for rIdx, row := range t.Rows {
			if t.IsSeparator[rIdx] {
				continue
			}
			var rCells []string
			for cIdx, cell := range row {
				uc := t.UncoloredRows[rIdx][cIdx]
				rCells = append(rCells, t.formatCell(cell, uc, cIdx))
			}
			sb.WriteString("| " + strings.Join(rCells, " | ") + " |\n")
		}

	default: // "basic"
		// Top border
		var topParts []string
		for _, w := range t.Widths {
			topParts = append(topParts, strings.Repeat("─", w+2))
		}
		sb.WriteString("╭" + strings.Join(topParts, "┬") + "╮\n")

		// Header row (centered headers)
		var hCells []string
		for i, h := range t.Headers {
			hCells = append(hCells, t.formatCellWithAlign(h, h, i, AlignCenter))
		}
		sb.WriteString("│ " + strings.Join(hCells, " │ ") + " │\n")

		// Middle border
		var midParts []string
		for _, w := range t.Widths {
			midParts = append(midParts, strings.Repeat("─", w+2))
		}
		sb.WriteString("├" + strings.Join(midParts, "┼") + "┤\n")

		// Data rows
		for rIdx, row := range t.Rows {
			if t.IsSeparator[rIdx] {
				var emptyParts []string
				for i := range t.Headers {
					emptyParts = append(emptyParts, strings.Repeat(" ", t.Widths[i]+2))
				}
				sb.WriteString("│" + strings.Join(emptyParts, "│") + "│\n")
