		stColored := FormattedStatus(pkg.Status, opts.UseColor)
		elStr := FormattedElapsed(pkg.Elapsed, true)
		covColored, covUncolored := FormattedCover(pkg, opts.CompareBase, opts.HasCompare, opts.UseColor)

		if pkg.Status == "NOTEST" {
			tbl.AddRow(
				[]string{stColored, elStr, pkgDisp, covColored, "--", "--", "--"},
				[]string{"NOTEST", elStr, pkgDisp, covUncolored, "--", "--", "--"},
			)
			tbl.AddRow(
				[]string{"", "", pkg.NoTestsMsg, "", "", "", ""},
				[]string{"", "", pkg.NoTestsMsg, "", "", "", ""},
			)
		} else if pkg.Status == "PANIC" {
			tbl.AddRow(
				[]string{stColored, elStr, pkgDisp, covColored, "--", "--", "--"},
				[]string{"PANIC", elStr, pkgDisp, covUncolored, "--", "--", "--"},
