{"command":"cat << 'EOF' > events.go
package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"regexp"
	"strconv"
	"strings"
)

var ErrNoParsableEvents = errors.New("no parsable events: Make sure to run go test with -json flag")

var covRegex = regexp.MustCompile(`coverage:\s*([0-9.]+)%`)

type StreamOptions struct {
	Follow           bool
	FollowWriter     io.Writer
	IncludeTimestamp bool
	Progress         bool
	UseColor         bool
}

func isFollowFiltered(out string) bool {
	s := strings.TrimSpace(out)
	if strings.HasPrefix(s, "=== RUN") ||
		strings.HasPrefix(s, "=== PAUSE") ||
		strings.HasPrefix(s, "=== CONT") ||
		strings.HasPrefix(s, "--- PASS:") ||
		strings.HasPrefix(s, "--- SKIP:") ||
		s == "PASS" ||
		s == "FAIL" {
		return true
	}
	return false
}

func ParseStream(r io.Reader, opts StreamOptions) (map[string]*Package, []*Package, error) {
	pkgMap := make(map[string]*Package)
	var pkgList []*Package

	scanner := bufio.NewScanner(r)
	buf := make([]byte, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)

	validEventCount := 0

	for scanner.Scan() {
		line := scanner.Bytes()
		if len(bytes.TrimSpace(line)) == 0 {
			return nil, nil, ErrNoParsableEvents
		}

		var ev TestEvent
		if err := json.Unmarshal(line, &ev); err != nil {
			return nil, nil, ErrNoParsableEvents
		}

		validEventCount++

		if ev.Package != "" {
			pkg, exists := pkgMap[ev.Package]
			if !exists {
				pkg = NewPackage(ev.Package)
				pkgMap[ev.Package] = pkg
				pkgList = append(pkgList, pkg)
			}

			// Pre-check output strings
			if ev.Test == "" && ev.Action == "output" {
				if strings.Contains(ev.Output, "[no test files]") {
					pkg.IsNoTests = true
					pkg.NoTestsMsg = "[no test files]"
				}
				if strings.Contains(ev.Output, "[no tests to run]") {
					pkg.IsNoTests = true
					pkg.NoTestsMsg = "[no tests to run]"
				}
			}

			// Follow output
			if opts.FollowWriter != nil || opts.Follow {
				if ev.Output != "" && !isFollowFiltered(ev.Output) {
					outLine := ev.Output
					if opts.IncludeTimestamp && ev.Time != "" {
						outLine = ev.Time + " " + ev.Output
					}
					w := opts.FollowWriter
					if w == nil {
						w = os.Stdout
					}
					fmt.Fprint(w, outLine)
				}
			}

			// Progress output
			if opts.Progress && ev.Test == "" {
				if (ev.Action == "pass" || ev.Action == "fail" || ev.Action == "skip") && !pkg.IsNoTests {
					st := strings.ToUpper(ev.Action)
					stText := FormattedStatus(st, opts.UseColor)
					fmt.Printf("[%s]\t%9.2fs\t%s\n", stText, ev.Elapsed, ev.Package)
				}
			}

			if ev.Test != "" {
				t, tExists := pkg.TestMap[ev.Test]
				if !tExists {
					t = &Test{Name: ev.Test, Package: ev.Package}
					pkg.TestMap[ev.Test] = t
					pkg.Tests = append(pkg.Tests, t)
				}

				if ev.Action == "output" {
					t.Output = append(t.Output, ev.Output)
					if strings.Contains(ev.Output, "panic:") {
						pkg.Panicked = true
						pkg.PanicTest = ev.Test
					}
				} else if ev.Action == "pass" {
					t.Status = "PASS"
					t.Elapsed = ev.Elapsed
					pkg.PassCount++
				} else if ev.Action == "fail" {
					t.Status = "FAIL"
					t.Elapsed = ev.Elapsed
					pkg.FailCount++
				} else if ev.Action == "skip" {
					t.Status = "SKIP"
					t.Elapsed = ev.Elapsed
					pkg.SkipCount++
				}
			} else {
				if ev.Action == "output" {
					pkg.Output = append(pkg.Output, ev.Output)
					matches := covRegex.FindStringSubmatch(ev.Output)
					if len(matches) > 1 {
						if c, err := strconv.ParseFloat(matches[1], 64); err == nil {
							pkg.Cover = c
							pkg.HasCover = true
						}
					}
					if strings.Contains(ev.Output, "[build failed]") {
						pkg.BuildFailed = true
					}
					if strings.Contains(ev.Output, "panic:") {
						pkg.Panicked = true
					}
				} else if ev.Action == "pass" {
					pkg.Elapsed = ev.Elapsed
					if !pkg.Panicked {
						pkg.Status = "PASS"
					}
				} else if ev.Action == "fail" {
					pkg.Elapsed = ev.Elapsed
					if !pkg.Panicked {
						pkg.Status = "FAIL"
					}
				} else if ev.Action == "skip" {
					pkg.Elapsed = ev.Elapsed
					if pkg.IsNoTests {
						pkg.Status = "NOTEST"
					}
				}
			}
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, nil, ErrNoParsableEvents
	}

	if validEventCount == 0 {
		return nil, nil, ErrNoParsableEvents
	}

	for _, pkg := range pkgList {
		if pkg.Panicked {
			pkg.Status = "PANIC"
		} else if pkg.BuildFailed {
			pkg.Status = "FAIL"
		} else if pkg.IsNoTests {
			pkg.Status = "NOTEST"
		} else if pkg.FailCount > 0 || pkg.Status == "FAIL" {
			pkg.Status = "FAIL"
		} else if pkg.Status == "PASS" || pkg.PassCount > 0 {
			pkg.Status = "PASS"
		}
	}

	return pkgMap, pkgList, nil
}
EOF"}

