func RenderTestTable(pkgList []*Package, opts RenderOptions) string {
	if !opts.All && !opts.Pass && !opts.Skip {
		return ""
	}

	type PkgTests struct {
		Pkg   *Package
		Tests []*Test
	}

	var allPkgTests []PkgTests
	totalTests := 0

	for _, pkg := range pkgList {
		var matched []*Test
		var passList []*Test
		var skipList []*Test
		var failList []*Test

		for _, t := range pkg.Tests {
			if t.Status == "FAIL" {
				failList = append(failList, t)
			} else if t.Status == "PASS" && (opts.All || opts.Pass) {
				passList = append(passList, t)
			} else if t.Status == "SKIP" && (opts.All || opts.Skip) {
				skipList = append(skipList, t)
			}
		}

		if opts.Slow > 0 {
			sort.Slice(passList, func(i, j int) bool { return passList[i].Elapsed > passList[j].Elapsed })
			if len(passList) > opts.Slow {
				passList = passList[:opts.Slow]
			}
			sort.Slice(skipList, func(i, j int) bool { return skipList[i].Elapsed > skipList[j].Elapsed })
			if len(skipList) > opts.Slow {
				skipList = skipList[:opts.Slow]
			}
		}

		matched = append(matched, passList...)
		matched = append(matched, skipList...)
		matched = append(matched, failList...)

		sort.Slice(matched, func(i, j int) bool { return matched[i].Elapsed > matched[j].Elapsed })

		if len(matched) > 0 {
			allPkgTests = append(allPkgTests, PkgTests{Pkg: pkg, Tests: matched})
			totalTests += len(matched)
		}
	}

	if totalTests == 0 {
		return ""
	}

	var sb strings.Builder

	if opts.Format == "markdown" {
		for _, pt := range allPkgTests {
			pkg := pt.Pkg
			sb.WriteString(fmt.Sprintf("## 📦 Package **`%s`**\n\n", pkg.Name))
			sb.WriteString(fmt.Sprintf("Tests: ✓ %d passed | %d skipped | %d failed\n\n", pkg.PassCount, pkg.SkipCount, pkg.FailCount))
			sb.WriteString("<details>\n\n<summary>Click for test summary</summary>\n\n")

			headers := []string{"Status", "Elapsed", "Test"}
			alignments := []Alignment{AlignCenter, AlignCenter, AlignLeft}
			tbl := NewTable(headers, alignments, opts.Format)

			for _, t := range pt.Tests {
				stColored := FormattedStatus(t.Status, opts.UseColor)
				elStr := FormattedElapsed(t.Elapsed, false)
				tbl.AddRow([]string{stColored, elStr, t.Name}, []string{t.Status, elStr, t.Name})
			}

			sb.WriteString(tbl.Render())
			sb.WriteString("</details>\n\n\n")
		}
	} else {
		headers := []string{"Status", "Elapsed", "Test", "Package"}
		alignments := []Alignment{AlignCenter, AlignCenter, AlignLeft, AlignLeft}
		tbl := NewTable(headers, alignments, opts.Format)

		for pkgIdx, pt := range allPkgTests {
			if pkgIdx > 0 {
				tbl.AddSeparatorRow()
			}
			pkgDisp := PackageDisplayName(pt.Pkg.Name, opts.TrimPath, opts.SmallScreen)
			for _, t := range pt.Tests {
				stColored := FormattedStatus(t.Status, opts.UseColor)
				elStr := FormattedElapsed(t.Elapsed, false)
				tbl.AddRow([]string{stColored, elStr, t.Name, pkgDisp}, []string{t.Status, elStr, t.Name, pkgDisp})
			}
		}

		sb.WriteString(tbl.Render())
	}

	return sb.String()
}

func RenderPackageSummaryTable(pkgList []*Package, opts RenderOptions) string {
	var displayPkgs []*Package

	allNotests := true
	for _, pkg := range pkgList {
		if pkg.Status != "NOTEST" {
			allNotests = false
			break
		}
	}

	for _, pkg := range pkgList {
		if pkg.Status != "NOTEST" || opts.NoTests || allNotests {
			displayPkgs = append(displayPkgs, pkg)
		}
	}

	if len(displayPkgs) == 0 {
		return ""
	}

	// Sort displayPkgs
	switch opts.Sort {
	case "elapsed":
		sort.Slice(displayPkgs, func(i, j int) bool {
			if displayPkgs[i].Elapsed == displayPkgs[j].Elapsed {
				return displayPkgs[i].Name < displayPkgs[j].Name
			}
			return displayPkgs[i].Elapsed > displayPkgs[j].Elapsed
		})
	case "cover":
		sort.Slice(displayPkgs, func(i, j int) bool {
			if displayPkgs[i].HasCover != displayPkgs[j].HasCover {
				return displayPkgs[i].HasCover
			}
			if displayPkgs[i].Cover == displayPkgs[j].Cover {
				return displayPkgs[i].Name < displayPkgs[j].Name
			}
			return displayPkgs[i].Cover > displayPkgs[j].Cover
		})
	default: // "name"
		sort.Slice(displayPkgs, func(i, j int) bool {
			isNoTestI := (displayPkgs[i].Status == "NOTEST")
			isNoTestJ := (displayPkgs[j].Status == "NOTEST")
			if isNoTestI != isNoTestJ {
				return !isNoTestI
			}
			return displayPkgs[i].Name < displayPkgs[j].Name
		})
	}

	headers := []string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"}
	alignments := []Alignment{AlignCenter, AlignCenter, AlignLeft, AlignCenter, AlignCenter, AlignCenter, AlignCenter}
	tbl := NewTable(headers, alignments, opts.Format)

	for _, pkg := range displayPkgs {
		pkgDisp := PackageDisplayName(pkg.Name, opts.TrimPath, opts.SmallScreen)
		stColored := FormattedStatus(pkg.Status, opts.UseColor)
		elStr := FormattedElapsed(pkg.Elapsed, true)
		if pkg.Status == "PANIC" {
			elStr = "0.00s"
		}
		covColored, covUncolored := FormattedCover(pkg, opts.CompareBase, opts.HasCompare, opts.UseColor)

		if pkg.Status == "NOTEST" {
			tbl.AddRow(
				[]string{stColored, elStr, pkgDisp, covColored, "--", "--", "--"},
				[]string{"NOTEST", elStr, pkgDisp, covUncolored, "--", "--", "--"},
			)
			tbl.AddRow(
				[]string{"", "", pkg.NoTestsMsg, "", "", "", ""},
				[]string{"", "", pkg.NoTestsMsg, "", "", "", ""},
			)
		} else if pkg.Status == "PANIC" {
			tbl.AddRow(
				[]string{stColored, elStr, pkgDisp, covColored, "--", "--", "--"},
				[]string{"PANIC", elStr, pkgDisp, covUncolored, "--", "--", "--"},
			)
		} else {
			passStr := fmt.Sprintf("%d", pkg.PassCount)
			failStr := fmt.Sprintf("%d", pkg.FailCount)
			skipStr := fmt.Sprintf("%d", pkg.SkipCount)
			tbl.AddRow(
				[]string{stColored, elStr, pkgDisp, covColored, passStr, failStr, skipStr},
				[]string{pkg.Status, elStr, pkgDisp, covUncolored, passStr, failStr, skipStr},
			)
		}
	}

	return tbl.Render()
}
