import subprocess
import os

def run_cmd(cmd, env=None):
    e = dict(os.environ)
    if env:
        e.update(env)
    p = subprocess.run(cmd, shell=True, capture_output=True, env=e)
    return p.returncode, p.stdout, p.stderr

def compare(name, cmd_orig, cmd_mine, env=None):
    code_o, out_o, err_o = run_cmd(cmd_orig, env)
    code_m, out_m, err_m = run_cmd(cmd_mine, env)

    ok = True
